export const ORACLE_SYSTEMS=Object.freeze({ZEN:"zen",ANGELS:"angels",ANIMALS:"animals"});

const ZEN_BY_ID=new Map(oshoZenReference.map(c=>[c.id,{...c,theme:`${c.group} · ${c.phase}`,detail:`${c.question} ${c.action}`}]));
const ANGEL_BY_ID=new Map(angelCatalog.map(c=>[c.id,{...c,theme:`${c.role} · ${c.family}`,detail:`${c.attribute}. ${c.keys.join(", ")}. Tradición de referencia: ${c.tradition}.`}]));
const ANIMAL_BY_ID=new Map(powerAnimals.map(c=>[c.id,{...c,theme:c.meaning,detail:`Su cualidad es ${c.meaning.toLowerCase()}. Observa dónde puedes aplicarla de manera concreta.`}]));
function canonicalOracleCard(system,card){
 const map=system===ORACLE_SYSTEMS.ZEN?ZEN_BY_ID:system===ORACLE_SYSTEMS.ANGELS?ANGEL_BY_ID:ANIMAL_BY_ID;
 return map.get(card.id)||card;
}

