function expressedMessage(meaning,memory,language="ES"){
 const raw=meaning.message,canonicalMessage=meaning.canonical?meaning.canonical.message:raw,normalized=normalize(canonicalMessage),seed=`${meaning.system}:${meaning.cardId}:${meaning.positionId}`;
 if(meaning.system!==ORACLE_SYSTEMS.ZEN)return sentence(raw);
 const table=ZEN_MESSAGE_VARIANTS_T[language]||ZEN_MESSAGE_VARIANTS_T.ES;
 let variants;
 if(/mira el patron|observar/.test(normalized))variants=table.observe;
 else if(/haz espacio|permit/.test(normalized))variants=table.allow;
 else if(/convierte la comprension|accion pequena|integr/.test(normalized))variants=table.integrate;
 else return sentence(raw);
 return chooseVariant(memory,"usedConceptPhrases",variants,seed);
}

