function signalFor(system,canonical,language="ES"){
 const key=normalize(`${canonical.name} ${themeOf(canonical)} ${canonical.message}`),T=SIGNAL_REASON_T[language]||SIGNAL_REASON_T.ES;
 const dictionaries={
  zen:{restrictive:/tension|contencion|division|distancia|peso|remordimiento|duelo|defensa|mascaras|dominio/,open:/espera|pausa|quietud|soledad|vacio|observador|huellas|velo|memoria/,supportive:/apertura|presencia|claridad|valor|encuentro|despertar|confianza|comprension|reparacion|expansion|prosperidad|creacion|integracion|juego|jubilo|cosecha/},
  angels:{restrictive:/purificacion|revision profunda|transicion y consuelo/,open:/tiempo y paciencia|silencio y aceptacion|noche y descanso|contemplacion|recogimiento|misterio/,supportive:/proteccion|valor|claridad|sanacion|sabiduria|justicia|armonia|esperanza|responsabilidad|gratitud|reconciliacion|coraje|construccion|direccion|creatividad/},
  animals:{restrictive:/atraccion|escorpion|cocodrilo/,open:/paciencia|atencion|observacion|transicion|profundidad|discernimiento|limpieza/,supportive:/vision|instinto|fortaleza|presencia|adaptacion|libertad|inteligencia|liderazgo|transformacion|renovacion|constancia|comunicacion|cooperacion|disciplina|construccion|equilibrio/},
 }[system];
 if(dictionaries.restrictive.test(key))return {kind:"restrictive",reason:T.restrictive};
 if(dictionaries.open.test(key))return {kind:"open",reason:T.open};
 if(dictionaries.supportive.test(key))return {kind:"supportive",reason:T.supportive};
 return {kind:"open",reason:T.defaultOpen};
}

function buildPositionMeaning(system,card,position,spreadId,language="ES"){
 const canonical=canonicalOracleCard(system,card),theme=themeOf(card,canonical),family=roleFamily(position),risk=system===ORACLE_SYSTEMS.ZEN?zenRisk(theme,canonical,language):system===ORACLE_SYSTEMS.ANGELS?angelRisk(theme,canonical,language):animalRisk(theme,canonical,language);
 return {system,spreadId,cardId:card.id,cardName:card.name,card,canonical,theme,message:card.message,positionId:position.id,position:position.label,role:position.role,semanticRole:position.semanticRole,answerMode:position.answerMode,question:position.question,family,risk,signal:signalFor(system,canonical,language)};
}

function indicativeRisk(value,language="ES"){if(language!=="ES")return value;return value.replace(/\bse vuelva\b/g,"se vuelve").replace(/\btermine\b/g,"termina").replace(/\bsupongas\b/g,"supones").replace(/\bhables\b/g,"hablas").replace(/\bdependa\b/g,"depende").replace(/\bimplique\b/g,"implica").replace(/\bmantenga\b/g,"mantiene").replace(/\bsustituyan\b/g,"sustituyen").replace(/\bpierda\b/g,"pierde").replace(/\babsorba\b/g,"absorbe").replace(/\bpase\b/g,"pasa").replace(/\bdeje\b/g,"deja");}

