const COMPARISON_TEXT_T={
 ES:{a:(n0,n1,ta,tb)=>`La lectura favorece ${n0} porque desarrolla ${ta}, mientras ${n1} deja mayor peso en ${tb}.`,b:(n0,n1,ta,tb)=>`La lectura favorece ${n1} porque conserva ${tb}, mientras ${n0} aumenta la exigencia asociada con ${ta}.`,balanced:(n0,n1,ta,tb)=>`Ambas opciones permanecen abiertas, pero no ofrecen lo mismo: ${n0} pone el acento en ${ta} y ${n1} en ${tb}.`,ending:{zen:"La diferencia útil está en cuál respuesta puedes sostener con mayor conciencia.",angels:"El criterio es elegir la opción que proteja mejor tus límites y responsabilidades.",animals:"Compara cuál cualidad responde mejor a las condiciones reales, no sólo a la preferencia inmediata."}},
 EN:{a:(n0,n1,ta,tb)=>`The reading favors ${n0} because it develops ${ta}, while ${n1} leans more heavily on ${tb}.`,b:(n0,n1,ta,tb)=>`The reading favors ${n1} because it preserves ${tb}, while ${n0} raises the demand tied to ${ta}.`,balanced:(n0,n1,ta,tb)=>`Both options stay open, but they don't offer the same thing: ${n0} emphasizes ${ta} and ${n1} emphasizes ${tb}.`,ending:{zen:"The useful difference lies in which answer you can sustain with greater awareness.",angels:"The criterion is choosing the option that best protects your limits and responsibilities.",animals:"Compare which quality responds better to the real conditions, not just the immediate preference."}},
 FR:{a:(n0,n1,ta,tb)=>`La lecture favorise ${n0} car cela développe ${ta}, tandis que ${n1} pèse davantage sur ${tb}.`,b:(n0,n1,ta,tb)=>`La lecture favorise ${n1} car cela conserve ${tb}, tandis que ${n0} augmente l'exigence liée à ${ta}.`,balanced:(n0,n1,ta,tb)=>`Les deux options restent ouvertes, mais elles n'offrent pas la même chose : ${n0} met l'accent sur ${ta} et ${n1} sur ${tb}.`,ending:{zen:"La différence utile se trouve dans la réponse que tu peux soutenir avec le plus de conscience.",angels:"Le critère est de choisir l'option qui protège le mieux tes limites et tes responsabilités.",animals:"Compare quelle qualité répond le mieux aux conditions réelles, pas seulement à la préférence immédiate."}},
 DE:{a:(n0,n1,ta,tb)=>`Die Lesung begünstigt ${n0}, weil sich dadurch ${ta} entfaltet, während ${n1} mehr Gewicht auf ${tb} legt.`,b:(n0,n1,ta,tb)=>`Die Lesung begünstigt ${n1}, weil dadurch ${tb} bewahrt wird, während ${n0} die mit ${ta} verbundene Anforderung erhöht.`,balanced:(n0,n1,ta,tb)=>`Beide Optionen bleiben offen, bieten aber nicht dasselbe: ${n0} betont ${ta}, ${n1} betont ${tb}.`,ending:{zen:"Der nützliche Unterschied liegt darin, welche Antwort du mit größerem Bewusstsein tragen kannst.",angels:"Das Kriterium ist, die Option zu wählen, die deine Grenzen und Verantwortlichkeiten am besten schützt.",animals:"Vergleiche, welche Qualität besser auf die realen Bedingungen reagiert, nicht nur auf die unmittelbare Vorliebe."}},
 PT:{a:(n0,n1,ta,tb)=>`A leitura favorece ${n0} porque desenvolve ${ta}, enquanto ${n1} deixa mais peso em ${tb}.`,b:(n0,n1,ta,tb)=>`A leitura favorece ${n1} porque conserva ${tb}, enquanto ${n0} aumenta a exigência associada a ${ta}.`,balanced:(n0,n1,ta,tb)=>`Ambas as opções permanecem abertas, mas não oferecem a mesma coisa: ${n0} coloca ênfase em ${ta} e ${n1} em ${tb}.`,ending:{zen:"A diferença útil está em qual resposta você consegue sustentar com mais consciência.",angels:"O critério é escolher a opção que melhor proteja seus limites e responsabilidades.",animals:"Compare qual qualidade responde melhor às condições reais, não apenas à preferência imediata."}},
};
function comparisonText(system,grammarId,answers,language="ES"){
 const isAct=grammarId==="act_or_not",a=byId(answers,isAct?"act":"path_a",isAct?"act_result":"result_a"),b=byId(answers,isAct?"not_act":"path_b",isAct?"not_act_result":"result_b"),endA=a.at(-1)||a[0],endB=b.at(-1)||b[0];
 const preference=endA.signal.kind===endB.signal.kind?"balanced":endA.signal.kind==="supportive"?"a":endB.signal.kind==="supportive"?"b":endA.signal.kind==="restrictive"?"b":"a";
 const T=COMPARISON_TEXT_T[language]||COMPARISON_TEXT_T.ES,names=(COMPARISON_NAMES_T[language]||COMPARISON_NAMES_T.ES)[isAct?"act":"paths"];
 const lower=text=>language==="DE"?text:text.toLowerCase(),ta=lower(endA.theme),tb=lower(endB.theme);
 const text=T[preference](names[0],names[1],ta,tb),ending=T.ending[system];
 return `${text} ${ending}`;
}

